import { get, handleApiError, post } from '@helpers/httpClient';

import { mapWorkoutTagToFront } from '../@mappers/workouts.mapper';
import { IWorkoutTagDTO } from '../@types/DTO/workouts.dto.types';

export const getWorkoutTagsAsync = async () => {
  const res = await get('/ajax/workouts/workout_tags_list.php').then<IWorkoutTagDTO[]>(
    handleApiError,
  );
  return res.map(mapWorkoutTagToFront);
};

export const addWorkoutTagUsageAsync = async (data: {
  id_workout: number;
  id_workout_tag: number;
}) => {
  return post('/ajax/workouts/workout_tag_usage_add.php', data).then<{ id: number }>(
    handleApiError,
  );
};

export const deleteWorkoutTagUsageAsync = async (id: number) => {
  return post('/ajax/workouts/workout_tag_usage_del.php', { id }).then<{ affected: number }>(
    handleApiError,
  );
};
