import React from 'react';

import CheckCircle from '@pohodnik/icons/svg/Signs/CheckCircle';
import XCircle from '@pohodnik/icons/svg/Signs/XCircle';
import clsx from 'clsx';
import { useNavigate } from 'react-router-dom';

import { selectUserAsync } from '@components/UserSelector/userSelectHelper';
import { AuthContext } from '@contexts/AuthContext';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohLoader from '@ui-kit/Loader';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';

import {
  acceptWorkoutInvite,
  addInviteUserToWorkout,
  deleteInviteUserFromWorkout,
  getWorkoutInvitesForWorkout,
  rejectWorkoutInvite,
} from '../@services/workoutsInvites.service';
import { IWorkoutShortInvite } from '../@types/workoutsInvites.types';

interface IWorkoutInvitesProps extends React.HTMLAttributes<HTMLDivElement> {
  id_workout: number;
  canEdit?: boolean;
}

const WorkoutInvites: React.FC<IWorkoutInvitesProps> = ({ id_workout, canEdit, ...rest }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [workoutInvites, setWorkoutInvites] = React.useState<IWorkoutShortInvite[]>([]);

  const navigate = useNavigate();
  const authContext = React.useContext(AuthContext);

  React.useEffect(() => {
    const fetchData = async () => {
      try {
        const fetchedInvites = await getWorkoutInvitesForWorkout(id_workout);
        setWorkoutInvites(fetchedInvites);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [id_workout]);

  const handleInviteFriend = async () => {
    if (!authContext.user) return;
    const selectedUser = await selectUserAsync({
      excludeIds: [authContext.user.id, ...workoutInvites.map((w) => w.user.id)],
    });
    const id_invite = await addInviteUserToWorkout(selectedUser.id, id_workout);

    setWorkoutInvites((cur) => {
      if (!authContext.user) return cur;
      return [
        ...cur,
        {
          id: id_invite,
          author: authContext.user,
          user: selectedUser,
          created_at: new Date(),
          accepted_at: null,
          rejected_at: null,
        },
      ];
    });
    notificationHelper.success(
      `Приглашение отправлено ${selectedUser.name} ${selectedUser.surname}`,
    );
  };

  if (isLoading) {
    return (
      <div className="d-flex align-items-center justify-content-center">
        <PohLoader />
      </div>
    );
  }

  if (err) {
    return (
      <div className="d-flex align-items-center justify-content-center">
        <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>
      </div>
    );
  }

  return (
    <aside {...rest} className={clsx('d-flex', rest.className)}>
      {workoutInvites.length > 0 && (
        <div className="w-100 d-flex flex-wrap align-items-start" style={{ gap: 4 }}>
          {workoutInvites
            .filter(
              (inv) =>
                authContext.user &&
                +authContext.user?.id === inv.user.id &&
                !inv.accepted_at &&
                !inv.rejected_at,
            )
            .map((invite) => {
              return (
                <PohAlert
                  variant={AlertVariant.Success}
                  key={invite.id}
                  className="d-flex align-items-center me-auto py-1"
                >
                  <small style={{ lineHeight: 1 }} className="me-1">
                    Приглашение
                    <span className="d-block">в тренировку</span>
                  </small>
                  <PohButton
                    variant={ButtonVariant.Success}
                    size={ButtonSize.Small}
                    onClick={async (e) => {
                      const el = e.target as HTMLButtonElement;
                      el.disabled = true;
                      const { workout_id } = await acceptWorkoutInvite(invite.id);
                      setWorkoutInvites((cur) =>
                        cur.map((ii) =>
                          ii.id === invite.id ? { ...ii, accepted_at: new Date() } : ii,
                        ),
                      );
                      notificationHelper.success('Приглашение принято');
                      navigate(`/workouts/${workout_id}`);
                      el.disabled = false;
                    }}
                    title={`${invite.author.name} пригласил(а) вас ${invite.created_at.toLocaleString()}`}
                  >
                    Принять
                  </PohButton>
                  &nbsp;
                  <PohButton
                    variant={ButtonVariant.Light}
                    size={ButtonSize.Small}
                    onClick={async (e) => {
                      const el = e.target as HTMLButtonElement;
                      el.disabled = true;
                      if (await confirmModal2('Отказаться от приглашения в тренировку?')) {
                        await rejectWorkoutInvite(invite.id);
                        setWorkoutInvites((cur) =>
                          cur.map((ii) =>
                            ii.id === invite.id ? { ...ii, rejected_at: new Date() } : ii,
                          ),
                        );
                        notificationHelper.success('Приглашение отклонено');
                      }

                      el.disabled = false;
                    }}
                    title={`${invite.author.name} пригласил(а) вас ${invite.created_at.toLocaleString()}`}
                  >
                    Отказаться
                  </PohButton>
                </PohAlert>
              );
            })}
          {workoutInvites.map((invite) => {
            return (
              <div
                key={invite.id}
                className="position-relative"
                title={[
                  'Приглашение в тренировку',
                  [invite.user.name, invite.user.surname].join(' '),
                  invite.created_at.toLocaleString(),
                ].join('\n')}
              >
                <PohAva src={invite.user.photo} alt={invite.user.name} />
                <aside className="position-absolute" style={{ right: 0, bottom: 0 }}>
                  {canEdit && !invite.accepted_at && authContext.user && (
                    <div className="toolbared p-1">
                      <PohButton
                        size={ButtonSize.Small}
                        icon={IconsEnum.trash}
                        className="show-on-hover"
                        onClick={async () => {
                          if (
                            await confirmModal2(
                              `Удалить приглашение для ${[invite.user.name, invite.user.surname].join(' ')}?`,
                            )
                          ) {
                            await deleteInviteUserFromWorkout(invite.id);
                            setWorkoutInvites((cur) => cur.filter((inv) => inv.id !== invite.id));
                            notificationHelper.success(`Приглашение удалено`);
                          }
                        }}
                      />
                    </div>
                  )}

                  {invite.accepted_at && <CheckCircle className="text-success" />}
                  {invite.rejected_at && <XCircle className="text-danger" />}
                </aside>
              </div>
            );
          })}
        </div>
      )}
      {canEdit && (
        <div>
          <PohButton
            size={ButtonSize.Small}
            variant={ButtonVariant.Success}
            onClick={handleInviteFriend}
            className="ms-md-2 me-auto text-nowrap"
          >
            Пригласить<span className="d-none d-lg-inline"> друга</span>
          </PohButton>
        </div>
      )}
    </aside>
  );
};

export default WorkoutInvites;
